import{_ as o,o as u,c as a,a0 as i}from"./chunks/framework.CSK6mTG2.js";const h=JSON.parse('{"title":"图像生成原理：Diffusion 模型怎么\\"画图\\"","description":"","frontmatter":{"title":"图像生成原理：Diffusion 模型怎么\\"画图\\"","author":"唐超","date":"2026-07-30T00:00:00.000Z"},"headers":[],"relativePath":"menuAI/image-generation-diffusion.md","filePath":"menuAI/image-generation-diffusion.md"}'),q={name:"menuAI/image-generation-diffusion.md"};function n(e,t,r,s,f,l){return u(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="图像生成原理-diffusion-模型怎么-画图" tabindex="-1">图像生成原理：Diffusion 模型怎么&quot;画图&quot; <a class="header-anchor" href="#图像生成原理-diffusion-模型怎么-画图" aria-label="Permalink to &quot;图像生成原理：Diffusion 模型怎么&quot;画图&quot;&quot;">​</a></h1><blockquote><p>它不是&quot;画&quot;出来的，是&quot;猜&quot;出来的——从一个全是噪声的画面，一点点&quot;擦&quot;出一张图。</p></blockquote><hr><h2 id="一、先想一个问题-ai-怎么-知道-一张猫长什么样" tabindex="-1">一、先想一个问题：AI 怎么&quot;知道&quot;一张猫长什么样？ <a class="header-anchor" href="#一、先想一个问题-ai-怎么-知道-一张猫长什么样" aria-label="Permalink to &quot;一、先想一个问题：AI 怎么&quot;知道&quot;一张猫长什么样？&quot;">​</a></h2><p>你让 AI 画一只猫，它凭什么能画出来？</p><p>答案很简单：**因为它看过无数的猫。**就像小朋友学画画，先看多了猫的照片，慢慢就知道&quot;猫有两个尖耳朵、胡须、圆眼睛&quot;。AI 也一样，只是它看得更多、记得更&quot;模糊&quot;。</p><p>但这里有个关键问题：大语言模型是&quot;一个词一个词往外蹦&quot;的，图像是二维的，AI 怎么才能&quot;一个词一个词&quot;把图画出来？</p><p>Diffusion 模型给了一个非常聪明的答案：<strong>我不直接画图，我反过来，从一张全是噪声的图开始，一步步把噪声&quot;擦掉&quot;，最后就得到了一张清晰的图。</strong></p><hr><h2 id="二、diffusion-的核心思路-从-糊-到-清-的逆过程" tabindex="-1">二、Diffusion 的核心思路：从&quot;糊&quot;到&quot;清&quot;的逆过程 <a class="header-anchor" href="#二、diffusion-的核心思路-从-糊-到-清-的逆过程" aria-label="Permalink to &quot;二、Diffusion 的核心思路：从&quot;糊&quot;到&quot;清&quot;的逆过程&quot;">​</a></h2><h3 id="先理解-正向过程-怎么把一张图变成噪声" tabindex="-1">先理解&quot;正向过程&quot;：怎么把一张图变成噪声 <a class="header-anchor" href="#先理解-正向过程-怎么把一张图变成噪声" aria-label="Permalink to &quot;先理解&quot;正向过程&quot;：怎么把一张图变成噪声&quot;">​</a></h3><p>想象你有一张清晰的照片。现在你做一件事：每次往照片上撒一点细小的噪点。撒一次，照片模糊一点；撒一百次，照片就完全看不清了，变成一张&quot;雪花屏&quot;。</p><p>这个过程就是 Diffusion 的&quot;正向过程&quot;——<strong>把一张清晰的图，一步一步加噪声，直到变成纯噪声</strong>。</p><p>你可以把它想象成一杯清水，每次滴一滴墨。滴得多了，水就彻底黑了。这就是正向的&quot;污染过程&quot;。</p><h3 id="再理解-逆向过程-怎么从噪声恢复出图像" tabindex="-1">再理解&quot;逆向过程&quot;：怎么从噪声恢复出图像 <a class="header-anchor" href="#再理解-逆向过程-怎么从噪声恢复出图像" aria-label="Permalink to &quot;再理解&quot;逆向过程&quot;：怎么从噪声恢复出图像&quot;">​</a></h3><p>正向过程好理解，但 AI 要做的是反过来：<strong>给定一张纯噪声的图，怎么一步一步把噪声去掉，恢复出一张清晰的图？</strong></p><p>这就是 Diffusion 模型的核心任务。</p><p>打个比方，就像你拿到一张被墨水完全染黑的白纸，你的任务是一点点把墨水擦掉，最后还原出原来的画。你不知道原画长什么样，但你&quot;看过&quot;足够多的画，知道&quot;这里大概该有只耳朵&quot;&quot;这里应该是条轮廓线&quot;。</p><p>每次你擦掉一点噪声，画面就清晰一点。擦了足够多次，一张全新的图就诞生了。</p><p><strong>所以 Diffusion 模型本质上不是在&quot;画&quot;图，而是在&quot;预测噪声&quot;——它猜的是&quot;当前这张图里，哪些像素是噪声，应该怎么修正&quot;。</strong></p><hr><h2 id="三、为什么-diffusion-有效-一个统计学直觉" tabindex="-1">三、为什么 Diffusion 有效？一个统计学直觉 <a class="header-anchor" href="#三、为什么-diffusion-有效-一个统计学直觉" aria-label="Permalink to &quot;三、为什么 Diffusion 有效？一个统计学直觉&quot;">​</a></h2><p>你可能会问：凭什么从噪声里能恢复出一张合理的图？万一恢复出来的图是张&quot;鬼画符&quot;呢？</p><p>这里的关键是概率。</p><p>想象一个巨大的&quot;图像空间&quot;——所有可能的像素组合都在里面，其中绝大多数都是无意义的噪点，只有极小一部分&quot;看起来像个东西&quot;。</p><p>Diffusion 模型学到的，就是这个&quot;有意义的图像&quot;在空间中长什么样。当你从一个纯噪声点开始，模型一步一步引导你往&quot;有意义的区域&quot;走，最终落在某一张具体的图上。</p><p>你可以把它想象成<strong>一个导航系统</strong>。你在一片大雾中（噪声），不知道往哪走。但模型告诉你&quot;往左走一点，前面像是有个轮廓&quot;&quot;再往前，这里该有个阴影&quot;——它不是在告诉你终点长什么样，而是在每一步告诉你&quot;往哪个方向走更合理&quot;。</p><hr><h2 id="四、stable-diffusion-的-加速秘诀-潜空间-latent-space" tabindex="-1">四、Stable Diffusion 的&quot;加速秘诀&quot;：潜空间（Latent Space） <a class="header-anchor" href="#四、stable-diffusion-的-加速秘诀-潜空间-latent-space" aria-label="Permalink to &quot;四、Stable Diffusion 的&quot;加速秘诀&quot;：潜空间（Latent Space）&quot;">​</a></h2><p>上面说的这套逻辑，理论上是成立的。但问题是：一张高清图动辄几百万像素，每步都要处理这么多数据，太慢了。</p><p>Stable Diffusion 的聪明之处，在于它不在&quot;像素空间&quot;里做 Diffusion，而是在&quot;潜空间&quot;（Latent Space）里做。</p><h3 id="什么是潜空间" tabindex="-1">什么是潜空间？ <a class="header-anchor" href="#什么是潜空间" aria-label="Permalink to &quot;什么是潜空间？&quot;">​</a></h3><p>你可以把潜空间理解成<strong>图像的&quot;压缩表示&quot;</strong>。</p><p>想象你有一张 1000×1000 的照片。直接存这 100 万个像素很占地方。但如果用一个编码器，把这 100 万个像素压缩成一个只有几千维的向量——这个向量就包含了图像的&quot;本质信息&quot;（比如&quot;这是一只橘猫，在沙发上，背景是窗户&quot;），而不需要记录每个像素的具体颜色。</p><p>Stable Diffusion 的做法是：</p><ol><li>先把图像编码到潜空间（用自编码器压缩）</li><li>在潜空间里做 Diffusion（加噪和去噪）</li><li>最后从潜空间解码回像素图像</li></ol><p>这就像你不在一张大画布上反复涂改，而是先在一个小草稿本上画草图，画好了再放大复制到画布上。<strong>潜空间让整个过程快了几个数量级。</strong></p><hr><h2 id="五、怎么控制画什么-条件-diffusion" tabindex="-1">五、怎么控制画什么？条件 Diffusion <a class="header-anchor" href="#五、怎么控制画什么-条件-diffusion" aria-label="Permalink to &quot;五、怎么控制画什么？条件 Diffusion&quot;">​</a></h2><p>如果 Diffusion 只是随机去噪，那每次生成的图都是随机的。怎么让模型&quot;画我想让它画的东西&quot;？</p><p>答案是<strong>条件化（Conditioning）</strong>——在去噪的每一步，都给模型一个&quot;提示&quot;，告诉它&quot;我要的是猫，不是狗&quot;。</p><p>最经典的条件就是<strong>文本提示（Text Prompt）</strong>。模型通过一个文本编码器（比如 CLIP），把&quot;一只橘猫在沙发上&quot;这句话转成一个向量，然后在每一步去噪时都参考这个向量。</p><p>你可以把它想象成：你请了一个画师，但每次动笔前你都跟他说&quot;记住，我要的是橘猫，不是黑猫&quot;&quot;背景是窗户，不是墙壁&quot;。画师每画一笔都记着这些要求，最后出来的作品自然符合你的描述。</p><p>除了文本，条件还可以是：</p><ul><li><strong>草图（Sketch）</strong>：给模型一个线稿，让它上色</li><li><strong>姿态图（Pose）</strong>：告诉模型人物的姿势</li><li><strong>已有图片（Image-to-Image）</strong>：基于一张图做修改</li></ul><hr><h2 id="六、扩散-vs-自回归-两种-生成-的哲学" tabindex="-1">六、扩散 vs 自回归：两种&quot;生成&quot;的哲学 <a class="header-anchor" href="#六、扩散-vs-自回归-两种-生成-的哲学" aria-label="Permalink to &quot;六、扩散 vs 自回归：两种&quot;生成&quot;的哲学&quot;">​</a></h2><p>你可能听说过，大语言模型是自回归的——一个字一个字往外蹦。那图像为什么不也用自回归？</p><p>其实早期确实有人试过，比如 PixelCNN，就是逐像素生成图像。但问题是：一张图的像素太多了，自回归太慢了，而且像素之间的长距离依赖关系很难建模。</p><p>Diffusion 换了一个思路：</p><table tabindex="0"><thead><tr><th>方法</th><th>生成方式</th><th>核心思想</th><th>类比</th></tr></thead><tbody><tr><td>自回归</td><td>逐个生成</td><td>基于已生成的，预测下一个</td><td>写字，一笔一画</td></tr><tr><td>Diffusion</td><td>全局去噪</td><td>从噪声出发，逐步修正整张图</td><td>雕塑，先粗雕再细雕</td></tr></tbody></table><p>**自回归是&quot;从前往后堆砖&quot;，Diffusion 是&quot;从模糊到清晰打磨&quot;。**两种方法各有优劣，但 Diffusion 在图像生成上的效果确实更好，所以现在几乎成了标配。</p><hr><h2 id="七、diffusion-的-小秘密-它其实在-作弊" tabindex="-1">七、Diffusion 的&quot;小秘密&quot;：它其实在&quot;作弊&quot; <a class="header-anchor" href="#七、diffusion-的-小秘密-它其实在-作弊" aria-label="Permalink to &quot;七、Diffusion 的&quot;小秘密&quot;：它其实在&quot;作弊&quot;&quot;">​</a></h2><p>说个有趣的点：Diffusion 模型生成图像时，并不是真的在&quot;擦&quot;噪声。它的数学本质，是<strong>学习了一个噪声的&quot;梯度场&quot;</strong>，告诉你&quot;当前这个点，应该往哪个方向变，才能更像真实的图&quot;。</p><p>每次去噪，模型只预测一小步的修正方向。把很多小步连在一起，就能从噪声一路走到真实图像区域。</p><p>这有点像什么呢？</p><p>想象你站在一座山的山顶，周围全是雾，你看不清路。但你手里有个指南针，每次告诉你&quot;往哪个方向下山&quot;。你不需要看到整座山，你只需要一步步跟着指南针走，最终就能到达山脚——也就是一张清晰的图。</p><p>这个&quot;指南针&quot;就是模型学的&quot;梯度&quot;。</p><hr><h2 id="八、diffusion-模型的局限" tabindex="-1">八、Diffusion 模型的局限 <a class="header-anchor" href="#八、diffusion-模型的局限" aria-label="Permalink to &quot;八、Diffusion 模型的局限&quot;">​</a></h2><p>虽然 Diffusion 很强，但它也不是完美的。</p><h3 id="_1-生成速度慢" tabindex="-1">1. 生成速度慢 <a class="header-anchor" href="#_1-生成速度慢" aria-label="Permalink to &quot;1. 生成速度慢&quot;">​</a></h3><p>因为要去噪几百步，生成一张图通常需要几秒钟甚至几十秒。对比 GPT 那种&quot;秒回&quot;的体验，图像生成还是慢了不少。这也是为什么大家都在研究&quot;少步数生成&quot;（比如蒸馏、一致性模型）。</p><h3 id="_2-对文本的理解有时很-迷" tabindex="-1">2. 对文本的理解有时很&quot;迷&quot; <a class="header-anchor" href="#_2-对文本的理解有时很-迷" aria-label="Permalink to &quot;2. 对文本的理解有时很&quot;迷&quot;&quot;">​</a></h3><p>你让它画&quot;一只红色的狗坐在蓝色的球上&quot;，它可能画成&quot;一只蓝色的狗坐在红色的球上&quot;。因为模型对&quot;空间关系&quot;和&quot;属性绑定&quot;的理解还不够精细。</p><h3 id="_3-版权和伦理问题" tabindex="-1">3. 版权和伦理问题 <a class="header-anchor" href="#_3-版权和伦理问题" aria-label="Permalink to &quot;3. 版权和伦理问题&quot;">​</a></h3><p>模型训练用了海量网络图片，其中很多受版权保护。生成的图风格和真实艺术家很像，也引发了版权争议。这又是一个&quot;技术跑得比伦理快&quot;的例子。</p><hr><h2 id="九、写给前端开发者的启发" tabindex="-1">九、写给前端开发者的启发 <a class="header-anchor" href="#九、写给前端开发者的启发" aria-label="Permalink to &quot;九、写给前端开发者的启发&quot;">​</a></h2><p>作为前端，你可能不会自己训练 Diffusion 模型，但你很可能用到它。</p><p>理解它的原理，能帮你在实际工作中做出更好的设计：</p><ul><li><strong>渐进式加载</strong>：既然图像是逐步去噪生成的，你可以做一个&quot;从模糊到清晰&quot;的渐进展示效果，而不是等全部生成完再显示</li><li><strong>用户引导</strong>：用户输入 Prompt 时，可以提供&quot; Prompt 优化建议&quot;，帮助模型生成更符合预期的图</li><li><strong>成本意识</strong>：图像生成的计算成本远高于文本生成。如果产品需要批量生成图像，要考虑缓存、预生成等策略</li><li><strong>错误处理</strong>：生成失败是常有的事（比如被安全过滤了），要做好 fallback 和用户提示</li></ul><hr><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>Diffusion 模型的核心，可以总结为一句话：</p><p><strong>它不是从无到有地&quot;画&quot;，而是从有到精地&quot;修&quot;——从一个充满噪声的混沌状态，一点一点修正出秩序和美。</strong></p><p>这个思路不只适用于图像。音频、视频、甚至 3D 模型，都在用类似的&quot;去噪&quot;思路生成。理解 Diffusion，你就理解了当今生成式 AI 最核心的技术之一。</p><p>下次看到 AI 画图的时候，你可以在心里默念：它不是在画，它是在<strong>猜</strong>——猜这片噪声背后，应该藏着什么。</p>',79)])])}const d=o(q,[["render",n]]);export{h as __pageData,d as default};
